; Asteroids Deluxe - memory map and symbol glossary
; GENERATED by mkdefines.py from the original Atari source archive.
;
; Names are the real ones: they come from DSTDEC.MAC, EAROM.MAC,
; PG0123.MAC and the LINKM load map DSTRD0.MAP, all written by the
; game's own authors.  The archive is the rev 2 build (MAME
; `astdelux2`) - DSTRD0.MAP's NMI $785C / PWRON $7CD7 are exactly the
; vectors in 036433-02.  Rev 3 moves page zero down by 7 bytes, so
; RAM addresses below apply to rev 2 only; the hardware block applies
; to every revision.
;
; The original assembler allowed '$' inside identifiers.  '$' is the
; hex prefix in this listing, so names like $INTCT are written INTCT
; here; the original spelling is noted in the comment.
;
; Address space (from the DSTRD0.MAC header):
;     0000-00FF  page 0   scratch / globals
;     0100-01FF  page 1   6502 stack (shares the page with SXP* cells)
;     0200-02FF  page 2   player 1 object state   } swapped by BNKSEL
;     0300-03FF  page 3   player 2 object state   } ($3C04 bit 7)
;     2000-3FFF  I/O
;     4000-47FF  vector RAM (2K) - the display list the DVG reads
;     4800-57FF  vector board ROM (4K) - 6502 code AND DVG data
;     6000-7FFF  program ROM (8K)
;     FFFA-FFFF  vectors, mirrored from 7FFA-7FFF

;--------------------------------------------------------------------
; HARDWARE / I/O  (all revisions)
;--------------------------------------------------------------------
THRKHZ     = $2001        ; 3KHZ SIGNAL
HALT       = $2002        ; D7=0 FOR HALTED
HYPSW      = $2003        ; HYPERSPACE SWITCH (D7=1) FOR ON
FIRESW     = $2004        ; FIRE BUTTON (D7=1 FOR ON)
DIAGSW     = $2005        ; DIGNOSTIC STEP SWITCH
LAM        = $2006        ; orig. $LAM.  SLAM SWITCH
STSTSW     = $2007        ; SELF TEST SWITCH (D7=1 FOR ON)
COINA      = $2400        ; orig. $COINA.  COIN SWITCHES (LEFT TO RIGHT, OFFSET=1)
STRT1      = $2403        ; 1 PLAYER START SWITCH (D7=1 FOR ON)
STRT2      = $2404        ; 2 PLAYER START SWITCH (D7=1 FOR ON)
THRUST     = $2405        ; THRUST (D7=1 FOR ON)
ROTR       = $2406        ; ROTATE RIGHT (D7=1 FOR ON)
ROTL       = $2407        ; ROTATE LEFT (D7=1 FOR ON)
OPTN1      = $2800        ; OPTION SWITCH 8=D1, SW7=D0, 0=ON (BONUS LEVEL)
OPTN2      = $2801        ; D1=SW6, D0=SW5
OPTN3      = $2802        ; D1=SW4, D0=SW3 (LIVES)
OPTN4      = $2803        ; D1=SW2, D0=SW1 (LANGUAGE)
POKEY      = $2C00        ; POKEY PORT (16 ADDRESSES)
OPTN5      = $2C08        ; D7=SW8,...,D0=SW1 (GAME PRICE)
RANDOM     = $2C0A        ; RANDOM NUMBER PORT
EAIN       = $2C40        ; EA READ PORT
GOADD      = $3000        ; RESTART VECTOR GEN
EADAL      = $3200        ; LATCH ADDR/DATA
WTDOG      = $3400        ; WATCH DOG
EXPSND     = $3600        ; EXPLOSION SOUND  D6-D7=PITCH,D2-D5=VOLUME
VGRESET    = $3800        ; VECTOR GEN RESET
EACTL      = $3A00        ; EA CONTROL LATCH
SLMP1      = $3C00        ; START LAMP 1(BIT 7)
SLMP2      = $3C01        ; START LAMP 2(BIT 7)
SPTEN      = $3C03        ; SHIP THRUST ENABLE
BNKSEL     = $3C04        ; BANK SELECT(80=PLAYER 2)
CCLFT      = $3C05        ; COIN COUNTER LEFT
CCMID      = $3C06        ; COIN COUNTER MIDDLE
CCRIT      = $3C07        ; COIN COUNTER RIGHT
NRESET     = $3E00        ; NOISE RESET
VECRAM     = $4000        ; VECTOR RAM

;--------------------------------------------------------------------
; CONSTANTS  (bit masks, not addresses)
;--------------------------------------------------------------------
DAST       = $01          ; orig. $DAST
DTHST      = $00          ; orig. $DTHST
