DEVSYS     = $00          ; .NE. FOR DEV SYS INTERFACE
EAC1       = $04          ; C1(INVERTED TO CHIP)
EAC2       = $02          ; C2
EACE       = $08          ; CHIP SELECT
EACK       = $01          ; CLOCK BIT

