CHIST      = $71          ; COLLISION HISTORY REGISTERS
SHDON      = $73          
GDELAY     = $74          ; DELAY BEFORE STARTING GAME
SYNC       = $75          ; FRAME COUNTER SYNC
FRAME      = $76          ; FRAME COUNTER
