;--------------------------------------------------------------------
; PAGE 1  (rev 2 addresses)
; The 6502 stack lives in this page; these cells sit above it.
;--------------------------------------------------------------------
SXPXL      = $0100        ; SHIP EXPLOSION CONTROLS. XL,YL,XH,YH
SXPYL      = $0108        
